# Verify the count calculation for m <= 100
count = 0
for m in range(1, 101):
    # Condition 1: m is not congruent to 1 mod 3
    if m % 3 != 1:
        # Condition 2: Exclude known exceptions m=2 and m=3
        if m != 2 and m != 3:
            count += 1

print(f"The count of valid m <= 100 is: {count}")

def check_count(M):
    count = 0
    for m in range(1, M + 1):
        # Condition: m >= 5 and m % 3 != 1
        if m >= 5 and m % 3 != 1:
            count += 1
    return count

count_100 = check_count(100)
print(f"Count for M=100: {count_100}")

# Check the count for the range [51, 100] specifically
def check_range(start, end):
    count = 0
    for m in range(start, end + 1):
        if m % 3 != 1:
            count += 1
    return count

count_51_100 = check_range(51, 100)
print(f"Count for M=[51, 100]: {count_51_100}")
